```python
import sys


def build_matrix(n, m, total_sum):
    # 创建全 0 矩阵，之后只在一个对称轨道上放置总和
    b = [[0] * m for _ in range(n)]

    # n 和 m 都是奇数，中心格子单独对称，可以放任意总和
    if n % 2 == 1 and m % 2 == 1:
        b[n // 2][m // 2] = total_sum
        return b

    # n 是奇数，m 是偶数，只能使用大小为 2 的左右对称轨道
    if n % 2 == 1 and m % 2 == 0:
        if total_sum % 2 != 0:
            return None
        value = total_sum // 2
        row = n // 2
        b[row][0] = value
        b[row][m - 1] = value
        return b

    # n 是偶数，m 是奇数，只能使用大小为 2 的上下对称轨道
    if n % 2 == 0 and m % 2 == 1:
        if total_sum % 2 != 0:
            return None
        value = total_sum // 2
        col = m // 2
        b[0][col] = value
        b[n - 1][col] = value
        return b

    # n 和 m 都是偶数，所有对称轨道大小都是 4
    if total_sum % 4 != 0:
        return None
    value = total_sum // 4
    b[0][0] = value
    b[0][m - 1] = value
    b[n - 1][0] = value
    b[n - 1][m - 1] = value
    return b


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    index = 0
    t = data[index]
    index += 1

    ans = []

    for _ in range(t):
        n = data[index]
        m = data[index + 1]
        index += 2

        # 读取原矩阵时只需要求元素总和
        total_sum = 0
        for _ in range(n * m):
            total_sum += data[index]
            index += 1

        b = build_matrix(n, m, total_sum)

        # 无法构造时输出 -1
        if b is None:
            ans.append("-1")
        else:
            # 输出构造出的对称矩阵
            for row in b:
                ans.append(" ".join(map(str, row)))

    sys.stdout.write("\n".join(ans))


if __name__ == "__main__":
    main()
